// Generated by OmniLang — Store hook: useTodoStore
import { useState, useCallback, useMemo } from 'react';

export function useTodoStore() {
    const [filter, setFilter] = useState<string>("all");
    const [items, setItems] = useState<string[]>([]);
    const [lastAction, setLastAction] = useState<string>("");
    const filterStatus = useMemo(() => { return filter; }, [filter]);
    const hasItems = useMemo(() => { return !(!(items) || items.length === 0); }, [items]);
    const totalCount = useMemo(() => { return items.length; }, [items]);
    const load = useCallback(() => {
        let raw = localStorage.getItem("todo-items");
        if (raw !== null) {
            setItems(JSON.parse(raw));
        }
    }, []);
    const save = useCallback(() => {
        localStorage.setItem("todo-items", JSON.stringify(items));
    }, []);
    const add = useCallback((text) => {
        if (text !== "") {
            setItems([items, text]);
            setLastAction("added: " + text);
            save();
        }
    }, []);
    const addTask = useCallback((title, priority, due) => {
        if (title === "") {
            return "error: title required";
        }
        if (priority < 1) {
            return "error: priority too low";
        }
        let entry = title;
        if (priority > 5) {
            entry = "[URGENT] " + title + " (P" + priority.toString() + " due " + due + ")";
            setItems([items, entry]);
            setLastAction("urgent task added");
            save();
            return "ok: urgent " + title;
        }
        entry = title + " [P" + priority.toString() + " due " + due + "]";
        setItems([items, entry]);
        setLastAction("task added");
        save();
        return "ok: " + title;
    }, []);
    const fetchReminders = useCallback(() => {
        if ((!(items) || items.length === 0)) {
            return "no items to sync";
        }
        let count = 0;
        let i = 0;
        while (i < items.length) {
            count = count + 1;
            i = i + 1;
        }
        setLastAction("synced " + count.toString() + " items");
        return "synced " + count.toString() + " reminders";
    }, []);
    const __actSetFilter = useCallback((mode) => {
        if (mode === "all") {
            setFilter("all");
        }
        if (mode === "urgent") {
            setFilter("urgent");
        }
        if (mode === "recent") {
            setFilter("recent");
        }
    }, []);
    const remove = useCallback(() => {
        setItems(items.slice(0, -1));
        setLastAction("removed last item");
        save();
    }, []);
    const clear = useCallback(() => {
        setItems([]);
        setLastAction("all cleared");
        save();
    }, []);
    return { load, save, add, addTask, fetchReminders, setFilter: __actSetFilter, remove, clear, filter, items, lastAction, filterStatus, hasItems, totalCount };
}
